// plumb for Pi: a thin adapter over plumb's host-neutral turn API (sp4 4.2).
// Generated by `plumb hosts install pi`; regenerate it rather than editing it.
// Each Pi event runs one `plumb hook <event> --host pi --format json` process and renders
// its TurnOutput: agent_context to the agent, owner_lines as a notice, status_line in the
// footer, and a block at most once per turn as a follow-up custom message.
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { spawn } from "node:child_process";

const PLUMB: string[] = __PLUMB_ARGV__;
const MARKER = "PLUMB_AGENT_SESSION";
const TIMEOUT_MS = 5000;
const EDIT_TOOLS = new Set(["edit", "write"]);

interface TurnOutput {
  agent_context: string[];
  owner_lines: string[];
  block: string | null;
  status_line: string;
}

const EMPTY: TurnOutput = { agent_context: [], owner_lines: [], block: null, status_line: "" };

// The marker reaches every command the bash tool runs; the owner-terminal guard holds anyway.
process.env[MARKER] = "pi";

function parse(stdout: string): TurnOutput {
  const text = stdout.trim();
  if (!text) return EMPTY;
  try {
    const data = JSON.parse(text);
    if (typeof data.systemMessage === "string") {
      return { ...EMPTY, owner_lines: data.systemMessage.split("\n") };
    }
    return { ...EMPTY, ...data };
  } catch {
    return { ...EMPTY, agent_context: text.split("\n") };
  }
}

function plumb(event: string, payload: Record<string, unknown>, cwd: string): Promise<TurnOutput> {
  return new Promise((resolve) => {
    let out = "";
    let done = false;
    const finish = (value: TurnOutput) => {
      if (!done) {
        done = true;
        resolve(value);
      }
    };
    try {
      const child = spawn(PLUMB[0], [...PLUMB.slice(1), "hook", event, "--host", "pi", "--format", "json"], {
        cwd,
        stdio: ["pipe", "pipe", "ignore"],
        windowsHide: true,
      });
      const timer = setTimeout(() => {
        child.kill();
        finish(EMPTY);
      }, TIMEOUT_MS);
      child.stdout.setEncoding("utf8");
      child.stdout.on("data", (chunk: string) => (out += chunk));
      child.on("error", () => finish(EMPTY));
      child.on("close", () => {
        clearTimeout(timer);
        finish(parse(out));
      });
      child.stdin.end(JSON.stringify({ ...payload, cwd }));
    } catch {
      finish(EMPTY);
    }
  });
}

export default function (pi: ExtensionAPI) {
  let pendingBrief: string[] = [];
  let blockedThisTurn = false;
  const injected = new Set<string>();

  const sessionId = (ctx: any): string => {
    try {
      return String(ctx.sessionManager.getSessionId() ?? "pi");
    } catch {
      return "pi";
    }
  };

  const show = (ctx: any, out: TurnOutput) => {
    if (!ctx.hasUI) return;
    if (out.status_line) ctx.ui.setStatus("plumb", out.status_line);
    if (out.owner_lines.length) ctx.ui.notify(out.owner_lines.join("\n"), "info");
  };

  pi.on("session_start", async (event: any, ctx: any) => {
    process.env[MARKER] = "pi";
    const source = event?.reason === "new" || event?.reason === "fork" ? "startup" : event?.reason;
    const out = await plumb("session-start", { session_id: sessionId(ctx), source }, ctx.cwd);
    pendingBrief = out.agent_context;
    show(ctx, out);
  });

  pi.on("before_agent_start", async (event: any, ctx: any) => {
    const text = String(event?.prompt ?? "");
    if (injected.has(text)) return; // plumb's own follow-up: never the owner's words, same turn
    blockedThisTurn = false; // a new owner prompt starts a new turn
    const out = await plumb("prompt", { session_id: sessionId(ctx), text }, ctx.cwd);
    const lines = [...pendingBrief, ...out.agent_context];
    pendingBrief = [];
    if (!lines.length) return;
    return { message: { customType: "plumb", content: lines.join("\n"), display: false } };
  });

  pi.on("tool_result", async (event: any, ctx: any) => {
    if (!EDIT_TOOLS.has(String(event?.toolName))) return;
    const path = event?.input?.path ?? event?.input?.file_path;
    if (typeof path === "string") void plumb("post-edit", { session_id: sessionId(ctx), path }, ctx.cwd);
  });

  pi.on("agent_end", async (_event: any, ctx: any) => {
    const out = await plumb("stop", { session_id: sessionId(ctx), stop_active: blockedThisTurn }, ctx.cwd);
    show(ctx, out);
    if (out.block && !blockedThisTurn) {
      blockedThisTurn = true;
      injected.add(out.block);
      pi.sendMessage(
        { customType: "plumb", content: out.block, display: true },
        { deliverAs: "followUp", triggerTurn: true },
      );
    }
  });

  pi.registerCommand("plumb", {
    description: "plumb: explain, status, review or confirm, in your own words",
    handler: async (args: string, _ctx: any) => {
      // exactly the owner's words: the message is logged as the owner's prompt, so plumb adds
      // nothing to it (no word of plumb's could then be relayed as the owner's ok)
      const words = String(args ?? "").trim() || "status";
      pi.sendUserMessage(`/plumb ${words}`);
    },
  });
}
